const ticketResponse = $('Get Ticket Snapshot').first().json;
const ticket = ticketResponse && ticketResponse.ticket;
if (!ticket || !ticket.id) { throw new Error('Ticket snapshot missing or malformed'); }
const pages = $input.all().map(item => item.json).filter(body => body && Array.isArray(body.comments));
if (pages.length === 0) { throw new Error('No comment pages fetched'); }
const lastPage = pages[pages.length - 1];
if (lastPage.next_page !== null && lastPage.next_page !== undefined) { throw new Error('Comment pagination incomplete: next_page still present'); }
const comments = pages.flatMap(body => body.comments);
if (typeof ticket.comment_count === 'number' && comments.length < ticket.comment_count) { throw new Error('Comment pagination incomplete: got ' + comments.length + ', expected ' + ticket.comment_count); }
return [{ json: { ticket, comments } }];

// Stage 2 source-only (p2-194): build a knowledge-source-v1 snapshot.
// Option A contract: idempotent identity = source_type + source_id +
// source_updated_at; snapshot_hash travels in references as evidence.
const source = $input.first().json;
const ticket = source.ticket;
const comments = source.comments;
if (!ticket || !ticket.id) { throw new Error('snapshot build: ticket missing'); }
if (!Array.isArray(comments)) { throw new Error('snapshot build: comments missing'); }
const payload = {
  ticket: ticket,
  comments: comments,
  comment_count: comments.length,
  pagination_complete: true,
};
const canonical = JSON.stringify(payload);
function sha256Hex(message) {
  const K = '428a2f98 71374491 b5c0fbcf e9b5dba5 3956c25b 59f111f1 923f82a4 ab1c5ed5 d807aa98 12835b01 243185be 550c7dc3 72be5d74 80deb1fe 9bdc06a7 c19bf174 e49b69c1 efbe4786 0fc19dc6 240ca1cc 2de92c6f 4a7484aa 5cb0a9dc 76f988da 983e5152 a831c66d b00327c8 bf597fc7 c6e00bf3 d5a79147 06ca6351 14292967 27b70a85 2e1b2138 4d2c6dfc 53380d13 650a7354 766a0abb 81c2c92e 92722c85 a2bfe8a1 a81a664b c24b8b70 c76c51a3 d192e819 d6990624 f40e3585 106aa070 19a4c116 1e376c08 2748774c 34b0bcb5 391c0cb3 4ed8aa4a 5b9cca4f 682e6ff3 748f82ee 78a5636f 84c87814 8cc70208 90befffa a4506ceb bef9a3f7 c67178f2'.split(' ').map(value => parseInt(value, 16));
  const bytes = new TextEncoder().encode(message);
  const bitLength = bytes.length * 8;
  const blockLength = Math.ceil((bytes.length + 9) / 64) * 64;
  const data = new Uint8Array(blockLength);
  data.set(bytes);
  data[bytes.length] = 0x80;
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  data[blockLength - 8] = high >>> 24;
  data[blockLength - 7] = high >>> 16;
  data[blockLength - 6] = high >>> 8;
  data[blockLength - 5] = high;
  data[blockLength - 4] = low >>> 24;
  data[blockLength - 3] = low >>> 16;
  data[blockLength - 2] = low >>> 8;
  data[blockLength - 1] = low;
  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;
  const rotr = (value, bits) => (value >>> bits) | (value << (32 - bits));
  for (let offset = 0; offset < blockLength; offset += 64) {
